"""Native hill-crest route and two-vehicle spawn for C101303.

Road IDs and hill classification must be source reviewed. Crest geometry and
adjacent driving lane are checked from actual Native waypoints before capture.
"""
from contextlib import contextmanager
import math


def _point(waypoint):
    p=waypoint.transform.location
    xyz=(float(p.x),float(p.y),float(p.z))
    if not all(math.isfinite(v) for v in xyz):raise ValueError('Nonfinite Native waypoint')
    return xyz

def _distance(a,b):
    return math.dist(_point(a),_point(b))

def select_hill_crest_route(native_map,start_transform,*,reviewed_road_id,
                            following_lane_id,target_lane_id,step_m=3.0,
                            minimum_length_m=30.0,minimum_crest_rise_m=0.5):
    if type(reviewed_road_id) is not int or type(following_lane_id) is not int or type(target_lane_id) is not int:
        raise ValueError('Source-reviewed Native road and lane IDs required')
    if target_lane_id==following_lane_id or step_m<=0 or minimum_length_m<=0 or minimum_crest_rise_m<=0:
        raise ValueError('Valid route geometry parameters required')
    start=native_map.get_waypoint(start_transform.location,project_to_road=False)
    if start is None or start.road_id!=reviewed_road_id or start.lane_id!=following_lane_id or start.is_junction:
        raise ValueError('Start is not in sourced following lane')
    path=[start];length=0.0
    for _ in range(math.ceil(minimum_length_m/step_m)+20):
        choices=[w for w in path[-1].next(step_m) if w.road_id==reviewed_road_id
                 and w.lane_id==following_lane_id and not w.is_junction
                 and str(w.lane_type).lower().endswith('driving')]
        if len(choices)!=1:break
        next_wp=choices[0];segment=_distance(path[-1],next_wp)
        if segment<=0 or not math.isfinite(segment):break
        length+=segment;path.append(next_wp)
        if length>=minimum_length_m:break
    if length<minimum_length_m:raise ValueError('Native following corridor too short')
    elevations=[_point(w)[2] for w in path]
    crest=max(range(1,len(path)-1),key=lambda i:elevations[i],default=None)
    if crest is None or elevations[crest]-max(elevations[0],elevations[-1])<minimum_crest_rise_m:
        raise ValueError('No measured Native hill crest')
    adjacent=[]
    for candidate in (path[crest].get_left_lane(),path[crest].get_right_lane()):
        if candidate is not None and candidate.road_id==reviewed_road_id and candidate.lane_id==target_lane_id and str(candidate.lane_type).lower().endswith('driving'):
            adjacent.append(candidate)
    if len(adjacent)!=1:raise ValueError('Selected adjacent driving lane missing at crest')
    return {'waypoints':path,'target_lane_waypoint':adjacent[0],
            'crest_waypoint_index':crest,'crest_rise_m':elevations[crest]-max(elevations[0],elevations[-1]),
            'corridor_length_m':length,'road_id':reviewed_road_id,
            'following_lane_id':following_lane_id,'target_lane_id':target_lane_id}

@contextmanager
def spawn_following_pair(world,blueprint,ego_transform,lead_transform,
                         *,minimum_initial_separation_m=4.0):
    owned=[]
    try:
        lead=world.try_spawn_actor(blueprint,lead_transform)
        if lead is None:raise ValueError('Native lead vehicle spawn failed')
        owned.append(lead)
        ego=world.try_spawn_actor(blueprint,ego_transform)
        if ego is None:raise ValueError('Native ego vehicle spawn failed')
        owned.append(ego)
        a,b=ego.get_location(),lead.get_location()
        separation=math.dist((a.x,a.y,a.z),(b.x,b.y,b.z))
        if separation<minimum_initial_separation_m:
            raise ValueError('Initial vehicle positions overlap')
        yield {'ego':ego,'lead':lead,'initial_center_separation_m':separation}
    finally:
        for actor in reversed(owned):actor.destroy()


def discover_hill_crest_route(native_map,*,minimum_length_m=30.0,step_m=3.0,minimum_crest_rise_m=0.5):
    """Search Native driving waypoints; return measured candidate for source review."""
    candidates=[]
    for start in native_map.generate_waypoints(step_m):
        if start.is_junction or not str(start.lane_type).lower().endswith('driving'):
            continue
        for adjacent in (start.get_left_lane(),start.get_right_lane()):
            if adjacent is None or adjacent.road_id!=start.road_id or adjacent.lane_id==start.lane_id:
                continue
            if not str(adjacent.lane_type).lower().endswith('driving'):
                continue
            try:
                candidate=select_hill_crest_route(native_map,start.transform,
                    reviewed_road_id=start.road_id,following_lane_id=start.lane_id,
                    target_lane_id=adjacent.lane_id,step_m=step_m,
                    minimum_length_m=minimum_length_m,minimum_crest_rise_m=minimum_crest_rise_m)
                candidates.append(candidate)
            except ValueError:
                continue
    if not candidates:raise ValueError('No measured Native hill-crest lane-change route')
    selected=max(candidates,key=lambda row:(row['crest_rise_m'],row['corridor_length_m']))
    selected['source_review_status']='native_geometry_candidate; legal highway and scenario eligibility unresolved'
    return selected

"""Four named source-camera actor construction at the pinned CPU profile.

Callers supply source-grounded static transforms for overview/approach/corner
and a relative driver transform. Real pixel coverage must be audited after run.
"""

from contextlib import contextmanager


SIZES = {"overview": (1920, 1080), "approach": (1280, 720),
         "reference_corner": (1280, 720), "driver_reference": (1280, 720)}


@contextmanager
def source_cameras(world, ego, transforms):
    if set(transforms) != set(SIZES):
        raise ValueError("All four named source-camera transforms required")
    sensors = {}
    try:
        for name, (width, height) in SIZES.items():
            blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
            blueprint.set_attribute("image_size_x", str(width))
            blueprint.set_attribute("image_size_y", str(height))
            blueprint.set_attribute("fov", "90")
            blueprint.set_attribute("sensor_tick", "0.05")
            kwargs = {"attach_to": ego} if name == "driver_reference" else {}
            sensor = world.spawn_actor(blueprint, transforms[name], **kwargs)
            if sensor is None:
                raise ValueError("Native camera spawn failed: " + name)
            sensors[name] = sensor
        yield sensors
    finally:
        for sensor in reversed(list(sensors.values())):
            sensor.stop()
            sensor.destroy()

"""Write original joined ego/lead bodies and velocities beside PipelineCapture.

PipelineCapture owns trace.jsonl, capture/evidence.jsonl and Native graphs. The
caller must join all four sensor frames for this world tick before this call.
"""
import json
import math

def _vertices(actor):
    transform=actor.get_transform()
    values=actor.bounding_box.get_world_vertices(transform)
    if len(values)<4:raise ValueError('Missing Native complete-body vertices')
    result=[[float(v.x),float(v.y)] for v in values]
    if not all(math.isfinite(v) for p in result for v in p):raise ValueError('Nonfinite Native body')
    return result

def _velocity(actor):
    value=actor.get_velocity()
    result=[float(value.x),float(value.y),float(value.z)]
    if not all(math.isfinite(v) for v in result):raise ValueError('Nonfinite Native velocity')
    return result

def _actor_row(actor,lane_id):
    return {'actor_id':actor.id,'lane_id':lane_id,'body_vertices_xy_m':_vertices(actor),
            'velocity_mps':_velocity(actor),'speed_source':'actor.get_velocity',
            'brake_applied':bool(actor.get_control().brake>0)}

def record_sample(frame_map,history_stream,snapshot,ego,lead,*,road_id,
                  ego_lane_id,lead_lane_id,surface_condition,traffic_actor_ids,
                  lane_change_started):
    frame,time=snapshot.frame,snapshot.timestamp.elapsed_seconds
    if type(lane_change_started) is not bool:raise ValueError('Missing lane change state')
    ego_row=_actor_row(ego,ego_lane_id);lead_row=_actor_row(lead,lead_lane_id)
    history={'frame':frame,'time_s':time,'road_id':road_id,
             'ego':ego_row,'lead':lead_row,'surface_condition':surface_condition,
             'traffic_actor_ids':list(traffic_actor_ids),'lane_change_started':lane_change_started}
    mapping=frame_map.append(frame,time)
    history_stream.write(json.dumps(history,allow_nan=False)+'\n')
    return {'video_frame':mapping['video_frame'],'history':history}

"""Original-frame following before a hill-crest lane change.

Reports complete-body geometry, both velocities, traffic and road condition.
Reasonable-and-prudent distance remains a legal judgment without a numeric cutoff.
"""
import hashlib
import json
import math
from pathlib import Path
from shapely.geometry import MultiPoint, Polygon

REQUIRED = ('road_context.json', 'vehicle_history.jsonl', 'video_frames.jsonl')

def number(value, label):
    if type(value) not in (int, float) or not math.isfinite(value):
        raise ValueError('Missing finite '+label)
    return float(value)

def vector(value, label, dimensions):
    if not isinstance(value, list) or len(value)!=dimensions:
        raise ValueError('Missing '+label)
    return tuple(number(v,label) for v in value)

def rows(path):
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]

def body(actor, label):
    values=actor.get('body_vertices_xy_m')
    if not isinstance(values,list) or len(values)<4:
        raise ValueError('Missing complete '+label+' body')
    polygon=MultiPoint([vector(v,label+' vertex',2) for v in values]).convex_hull
    if polygon.area<=0:raise ValueError('Degenerate '+label+' body')
    return polygon

def analyze(root:Path)->dict:
    root=Path(root);hashes={}
    for name in REQUIRED:
        path=root/name
        if not path.is_file():raise ValueError('Missing original source: '+name)
        hashes[name]=hashlib.sha256(path.read_bytes()).hexdigest()
    ctx=json.loads((root/'road_context.json').read_text())
    for key in ('native_map_id','highway_id','road_id','following_lane_id',
                'target_lane_id','hill_crest_source','lane_geometry_source',
                'surface_source','traffic_source','route_source'):
        if ctx.get(key) is None:raise ValueError('Missing sourced road context: '+key)
    if ctx['following_lane_id']==ctx['target_lane_id']:
        raise ValueError('Lane change target equals following lane')
    forward=vector(ctx.get('following_forward_xy'),'following direction',2)
    norm=math.hypot(*forward)
    if norm==0:raise ValueError('Zero following direction')
    fx,fy=forward[0]/norm,forward[1]/norm
    lx,ly=-fy,fx
    original,frames=rows(root/'vehicle_history.jsonl'),rows(root/'video_frames.jsonl')
    if len(original)<3 or len(original)!=len(frames):raise ValueError('Incomplete following/frame history')
    previous=(-1,-math.inf);samples=[];first_change=None
    for i,(row,frame) in enumerate(zip(original,frames)):
        fid,time=row.get('frame'),number(row.get('time_s'),'time')
        if type(fid) is not int or fid<=previous[0] or time<=previous[1]:
            raise ValueError('Nonmonotone original history')
        previous=fid,time
        if frame.get('video_frame')!=i or frame.get('carla_frame')!=fid or frame.get('time_s')!=time:
            raise ValueError('Original frame join failed')
        if row.get('road_id')!=ctx['road_id']:
            raise ValueError('Ego on wrong road')
        ego,lead=row.get('ego'),row.get('lead')
        if not isinstance(ego,dict) or not isinstance(lead,dict):raise ValueError('Missing both vehicle sources')
        if ego.get('actor_id')==lead.get('actor_id') or not ego.get('actor_id') or not lead.get('actor_id'):
            raise ValueError('Distinct Native vehicle identities required')
        eb,lb=body(ego,'ego'),body(lead,'lead')
        ev=vector(ego.get('velocity_mps'),'ego velocity',3)
        lv=vector(lead.get('velocity_mps'),'lead velocity',3)
        if ego.get('speed_source')!='actor.get_velocity' or lead.get('speed_source')!='actor.get_velocity':
            raise ValueError('Original Native velocities required')
        if ego.get('lane_id') not in (ctx['following_lane_id'],ctx['target_lane_id']):
            raise ValueError('Unexpected ego lane')
        if lead.get('lane_id')!=ctx['following_lane_id']:
            raise ValueError('Lead left sourced following lane')
        if row.get('surface_condition') not in ('dry','wet','snow','ice','other_sourced'):
            raise ValueError('Road condition missing')
        traffic=row.get('traffic_actor_ids')
        if not isinstance(traffic,list) or not all(type(a) is int for a in traffic):
            raise ValueError('Traffic inventory missing')
        if ego['actor_id'] not in traffic or lead['actor_id'] not in traffic:
            raise ValueError('Subject and lead absent from traffic inventory')
        ego_long=[x*fx+y*fy for x,y in eb.exterior.coords]
        lead_long=[x*fx+y*fy for x,y in lb.exterior.coords]
        ego_lat=[x*lx+y*ly for x,y in eb.exterior.coords]
        lead_lat=[x*lx+y*ly for x,y in lb.exterior.coords]
        longitudinal_gap=min(lead_long)-max(ego_long)
        lateral_overlap=min(max(ego_lat),max(lead_lat))-max(min(ego_lat),min(lead_lat))
        same_lane=ego['lane_id']==ctx['following_lane_id']
        following=same_lane and longitudinal_gap>0 and lateral_overlap>0
        change=row.get('lane_change_started')
        if type(change) is not bool:raise ValueError('Lane-change event missing')
        if change and first_change is None:first_change={'frame':fid,'time_s':time}
        if first_change and not change:raise ValueError('Lane-change event regressed')
        samples.append({'frame':fid,'time_s':time,'ego_lane_id':ego['lane_id'],
                        'lead_lane_id':lead['lane_id'],'following':following,
                        'longitudinal_body_gap_m':longitudinal_gap,
                        'lateral_body_overlap_m':lateral_overlap,
                        'ego_speed_mps':math.sqrt(sum(v*v for v in ev)),
                        'lead_speed_mps':math.sqrt(sum(v*v for v in lv)),
                        'lead_brake':bool(lead.get('brake_applied')),
                        'surface_condition':row['surface_condition'],
                        'traffic_actor_ids':traffic,'lane_change_started':change})
    if first_change is None:raise ValueError('No observed lane change')
    before=[s for s in samples if s['time_s']<first_change['time_s']]
    if not before or not any(s['following'] for s in before):
        raise ValueError('No observed following before lane change')
    during=[s for s in samples if s['following']]
    return {'format':'worker-hill-crest-following-observations','sources':hashes,
            'first_lane_change':first_change,'following_start':{'frame':during[0]['frame'],'time_s':during[0]['time_s']},
            'following_end':{'frame':during[-1]['frame'],'time_s':during[-1]['time_s']},
            'following_overlaps_lane_change':any(s['time_s']>=first_change['time_s'] for s in during),
            'minimum_sampled_body_gap_m':min(s['longitudinal_body_gap_m'] for s in before if s['following']),
            'samples':samples,'reasonable_and_prudent_judgment':'unresolved; no statutory numeric gap',
            'legal_conclusion':'unresolved'}
